<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/student_inventory_create_panel.php';require_once __DIR__.'/../app/student_inventory_move_panel.php';security_headers();student_private_headers();$db=database();$student=student_account_current($db);if(!$student){header('Location: /aluno/login.php?next=%2Faluno%2Finventario.php',true,303);exit;}$studentId=(int)$student['id'];try{student_tool_require($db,$studentId,'lab_inventory');}catch(Throwable){http_response_code(403);exit('Ferramenta indisponível.');}$error='';$submittedAction=(string)($_POST['action']??'');
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!verify_csrf('student-inventory',$_POST['_csrf']??null))$error='Solicitação inválida.';else try{$action=(string)($_POST['action']??'create');if($action==='create')student_inventory_create($db,$studentId,$_POST);elseif($action==='move'){
  $amount=student_workbench_float($_POST['amount']??null);
  if($amount===null||!is_finite($amount)||$amount<=0||round($amount,3)!==$amount)throw new RuntimeException('Informe uma quantidade válida (até três casas decimais).');
  $direction=(string)($_POST['direction']??'');
  $types=['in'=>[1,'in'],'out'=>[-1,'consume'],'adjust_up'=>[1,'adjust'],'adjust_down'=>[-1,'adjust']];
  if(!isset($types[$direction]))throw new RuntimeException('Escolha o tipo de movimentação.');
  $note=student_workspace_text($_POST['note']??'',500);
  if(str_starts_with($direction,'adjust_')&&trim($note)==='')throw new RuntimeException('Informe o motivo da correção de saldo.');
  $uuid=(string)($_POST['movement_uuid']??'');
  if(!preg_match('/^[a-zA-Z0-9-]{16,80}$/D',$uuid))throw new RuntimeException('Solicitação inválida. Reabra a movimentação.');
  student_inventory_move($db,$studentId,(int)($_POST['item_id']??0),$types[$direction][0]*$amount,$types[$direction][1],$note,null,null,true,$uuid);
}elseif($action==='archive')student_inventory_archive($db,$studentId,(int)($_POST['item_id']??0));else throw new RuntimeException('Ação inválida.');header('Location: /aluno/inventario.php?saved='.($action==='move'?'move':'1').($action==='move'?'#inventory-item-'.(int)($_POST['item_id']??0):''),true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}
}
$failedCreate=$error!==''&&$submittedAction==='create';$createDraft=$failedCreate?$_POST:[];$failedMove=$error!==''&&$submittedAction==='move';
$items=student_inventory_items($db,$studentId);if($failedMove&&!in_array((int)($_POST['item_id']??0),array_map(static fn(array $row):int=>(int)$row['id'],$items),true))$failedMove=false;$movements=student_inventory_movements($db,$studentId,0,40);$lowCount=0;$solutionCount=0;foreach($items as $item){if((string)$item['item_kind']==='solution')$solutionCount++;if($item['minimum_quantity']!==null&&(float)$item['quantity']<=(float)$item['minimum_quantity'])$lowCount++;}student_shell_start('Inventário do laboratório',null,$student);?>
<div class="student-appbar"><a class="student-back" href="/aluno/ferramentas.php">← Laboratório</a></div><div class="student-page-heading"><div><p class="student-kicker">Laboratório · estoque físico</p><h1 class="student-title">Inventário</h1><p class="student-lab-stock-intro">Itens que <strong>existem fisicamente no laboratório</strong>. Registre entradas e saídas para manter o saldo correto.</p></div><button class="button button-secondary" type="button" data-inventory-new-toggle aria-expanded="<?=$failedCreate?'true':'false'?>" aria-controls="student-inventory-new">Novo item</button></div><?php if(isset($_GET['saved'])):?><p class="ui-alert ui-alert-notice" role="status"><?=($_GET['saved']??'')==='move'?'Movimentação registrada.':'Inventário atualizado.'?></p><?php endif;?><?php if($error&&!$failedCreate&&!$failedMove):?><p class="ui-alert ui-alert-error" role="alert"><?=h($error)?></p><?php endif;?>

<dialog class="student-create-dialog" data-student-editor-dialog><div data-student-editor></div></dialog>
<?php student_inventory_create_panel($createDraft,$failedCreate?$error:'',csrf_token('student-inventory')); ?>
<section class="student-section" data-student-local-key="inventory-stock"><div class="student-stock-section-heading"><div><p class="student-kicker">Estoque</p><h2 class="student-subtitle">O que tenho disponível</h2></div></div><?php if(!$items):?><div class="student-empty student-preparation-empty"><strong>Seu inventário ainda está vazio.</strong><p>Comece cadastrando um produto que você realmente tem no laboratório. Se você quer apenas salvar uma receita de revelação para repetir depois, crie uma predefinição em vez de um item de estoque.</p><button class="button button-primary" type="button" data-inventory-new-toggle aria-expanded="<?=$failedCreate?'true':'false'?>" aria-controls="student-inventory-new">Adicionar primeiro item</button></div><?php else:?><div class="student-inventory-list"><?php foreach($items as $item):$low=$item['minimum_quantity']!==null&&(float)$item['quantity']<=(float)$item['minimum_quantity'];?><article id="inventory-item-<?=(int)$item['id']?>" class="student-inventory-item<?=$low?' is-low':''?>"><div class="student-inventory-main"><span class="student-status"><?=$item['item_kind']==='solution'?'Solução preparada':'Insumo'?></span><h3><?=h((string)$item['name'])?></h3><p><?=h(trim((string)$item['lot_code'])!==''?'Lote '.(string)$item['lot_code']:'Sem lote')?><?=trim((string)$item['location'])!==''?' · '.h((string)$item['location']):''?><?php if(trim((string)$item['expires_at'])!==''):?> · validade <?=h((string)$item['expires_at'])?><?php endif;?></p></div><div class="student-inventory-balance"><strong><?=h(student_workbench_number((float)$item['quantity']))?></strong><span><?=h((string)$item['unit'])?> disponíveis</span><?php if($low):?><small>estoque baixo</small><?php endif;?></div><div class="student-inventory-item-actions"><?php student_inventory_move_panel($item,csrf_token('student-inventory'),$failedMove?$_POST:[],$failedMove?$error:''); ?><details class="student-inventory-options"><summary>Mais opções</summary><div class="student-inventory-options-content"><a class="button button-secondary button-compact" href="/aluno/inventario-item.php?id=<?=(int)$item['id']?>" data-student-editor-link>Editar item</a><form method="post" data-student-local-form data-local-refresh="inventory-stock inventory-history" data-local-confirm="Arquivar este item? Ele sairá do estoque ativo, mas o histórico será preservado."><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-inventory'))?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><button class="button button-danger button-compact" type="submit">Arquivar</button></form></div></details></div></article><?php endforeach;?></div><?php endif;?></section>
<details class="student-stock-metrics" data-inventory-metrics><summary>Resumo do estoque <span><?=count($items)?> <?=count($items)===1?'item':'itens'?></span></summary><section class="student-stock-summary" aria-label="Resumo do inventário"><article><span>Itens ativos</span><strong><?=count($items)?></strong><small>insumos e soluções disponíveis</small></article><article><span>Estoque baixo</span><strong><?=$lowCount?></strong><small>itens no mínimo definido ou abaixo</small></article><article><span>Soluções preparadas</span><strong><?=$solutionCount?></strong><small>banhos ou soluções fisicamente disponíveis</small></article></section></details>
<div class="student-lab-crosslink"><div><strong>Procurando uma condição de revelação para reutilizar?</strong><p>Uma predefinição salva parâmetros como diluição, temperatura e tempo. Ela não significa que a solução esteja preparada ou disponível em estoque.</p></div><a class="button button-secondary button-compact" href="/aluno/preparos.php">Ver predefinições</a></div>
<section class="student-section" data-student-local-key="inventory-history"><div class="student-stock-section-heading"><div><p class="student-kicker">Histórico</p><h2 class="student-subtitle">O que alterou o saldo</h2></div><p>As movimentações ficam registradas para você conseguir entender por que uma quantidade aumentou ou diminuiu.</p></div><?php if(!$movements):?><div class="student-empty">Nenhuma movimentação registrada.</div><?php else:?><div class="student-inventory-history"><?php foreach($movements as $movement):?><div><span><?=h((string)$movement['item_name'])?></span><strong class="<?=$movement['quantity_delta']<0?'is-out':'is-in'?>"><?=($movement['quantity_delta']>0?'+':'').h(student_workbench_number((float)$movement['quantity_delta'])).' '.h((string)$movement['unit'])?></strong><small><?=h(match((string)$movement['movement_type']){'in'=>'Entrada','consume'=>'Saída / consumo','adjust'=>'Correção',default=>'Movimentação'})?> · <?=h(substr(str_replace('T',' ',(string)$movement['created_at']),0,16))?> UTC<?php if(trim((string)$movement['note'])!==''):?> · <?=h((string)$movement['note'])?><?php endif;?><?php if((int)($movement['test_id']??0)>0):?> · <a href="/aluno/teste.php?id=<?=(int)$movement['test_id']?>">abrir registro</a><?php endif;?></small></div><?php endforeach;?></div><?php endif;?></section><script defer src="/assets/student-inventory-movement.js"></script><?php student_shell_end();
